const expected = ['content_jobs','job_events','content_revisions','media_assets','site_configs'];
const found = $("04 Verify Tables Exist").all().map(i => i.json.table_name).filter(Boolean);
const missing = expected.filter(t => !found.includes(t));
const errors = missing.map(t => ({ code: 'TABLE_MISSING', message: 'Expected table not found after setup: ' + t }));
const passed = missing.length === 0;
return [{
  json: {
    success: passed,
    jobId: null,
    status: passed ? 'DB_READY' : 'DB_SETUP_FAILED',
    message: passed
      ? 'All automation tables exist and the development test site config is present.'
      : 'One or more automation tables are missing after setup.',
    data: { tablesFound: found, tablesMissing: missing, devSiteKey: 'mohamed-arslan-test-site' },
    warnings: [],
    errors,
    nextAllowedActions: [],
  },
}];
